function links(v) {
  if (Array.isArray(v)) {
    return v.map(function (l) {
      if (typeof l === 'string') {
        const m = l.match(/^\s*(.*?)\s*(?:\||=>|->|::)\s*(https?:\/\/\S+)\s*$/);
        if (m) return { anchor: m[1], url: m[2] };
        const md = l.match(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/);
        if (md) return { anchor: md[1], url: md[2] };
        return { anchor: '', url: l.trim() };
