    }).filter(function (l) { return l.url; });
  }
  return arr(v).map(function (line) {
    const m = line.match(/^\s*(.*?)\s*(?:\||=>|->|::)\s*(https?:\/\/\S+)\s*$/);
    if (m) return { anchor: m[1], url: m[2] };
