      '- الدولة: ' + (b.country || '-'),
      '- الأسواق المستهدفة: ' + ((b.markets || []).join('، ') || '-'),
      '- الخدمات: ' + ((b.services || []).join('، ') || '-'),
      '- نبرة الكتابة: ' + (b.tone || '-'),
      '- نقاط الإثبات المتاحة (Social Proof): ' + ((b.proof_points || []).join(' | ') || '-'),
      '- صيغ الـ CTA المسموحة: ' + ((b.cta_options || []).join(' | ') || '-')
