  const m = s.match(/<<<SECTION>>>([\s\S]*?)<<<END_SECTION>>>/);
  if (m) return m[1].trim();
  const open = s.indexOf('<<<SECTION>>>');
  if (open >= 0) return s.slice(open + 13).trim();
