  const head = i < secs.length - 1 ? H.clip(secs[i + 1].md.split('\n').slice(0, 6).join('\n'), 700) : '(هذا آخر قسم)';
  return ['### نهاية القسم السابق (للانتقال فقط — لا تعد كتابته)', tail, '',
