  L.push('- طول قسمك: **' + t.current_words + '** كلمة → المطلوب **' + t.target_words + '** كلمة (±10%)' +
         (Math.abs(dw) >= 15 ? (dw > 0 ? '  ⇒ **أضف ~' + dw + ' كلمة من محتوى حقيقي، لا حشو**' : '  ⇒ **احذف ~' + Math.abs(dw) + ' كلمة من الحشو**') : '  ⇒ الطول مناسب'));
  if (kw && t.want_kw) {
    const dk = t.target_kw - t.current_kw;
