    } else {
      kept.push({ key: p.key, heading: p.heading || (old && old.heading) || '', md: p.md });
    }
  });
  (state.sections || []).forEach(function (s) {
    if (!kept.some(function (k) { return k.key === s.key; })) kept.push(s);
