  if (Array.isArray(patch) || typeof patch !== 'object') return patch;
  const out = Object.assign({}, base && typeof base === 'object' && !Array.isArray(base) ? base : {});
  for (const k of Object.keys(patch)) out[k] = H.deepMerge(out[k], patch[k]);
  return out;
};
