    L.push('   القسم المقترح: ' + (e.section || '-'));
    L.push('   سطر المصادر: ' + (e.citation_line || ''));
  });
  const rm = (state.evidence && state.evidence.must_remove) || [];
  if (rm.length) L.push('\n**ممنوع ذكر هذه الادعاءات بأي رقم:** ' + rm.join(' | '));
