  const L = ['### تقرير المفتش الآلي (أرقام لا آراء — ملزمة)'];
  L.push('- الحالة: ' + (m.pass ? 'ناجح ✅' : 'راسب ❌ (' + fails.length + ' مخالفة)'));
  (m.checks || []).forEach(function (c) {
