    key: '__faq__', order: plan.length,
    heading: 'الأسئلة الشائعة (FAQ)',
    purpose: 'أسئلة حقيقية يسألها الباحث بإجابات مباشرة قصيرة صالحة لـ FAQ Schema',
    word_budget: faqWords, format: 'faq',
