  });
  if (!used.length) return '';
  const L = ['## المصادر المستخدمة', ''];
  used.forEach(function (e) {
    L.push('- ' + (e.citation_line ||
      ((e.publisher || '') + ' — «' + (e.page_title || '') + '»: ' + e.url +
       ' — المعلومة المستخدمة: ' + (e.figure || ''))));
