    const meta = (c.json && c.json.meta) || {};
    const raw  = responses[i] ? responses[i].json : null;
    const text = H.readText(raw);
    parts.push({
      key: meta.section_key,
      order: meta.order,
      heading: meta.section_heading || '',
      md: H.grabSection(text),
      err: H.apiError(raw),
      truncated: H.truncated(raw, text)
