  state.sections = kept.filter(function (s) { return s.key !== '__sources__'; });
  state.article = H.joinSections(state.sections);
  if (!cfg.rules || cfg.rules.auto_sources_section !== false) {
    const src = H.buildSourcesSection(state);
    if (src) {
