        meta: {
          persona_id: personaId,
          persona_name: persona.name,
          persona_title: persona.title,
          emoji: persona.emoji || '🗣️',
          output_mode: persona.output_mode || 'json',
          stage: (extra && extra.stage) || 'unknown'
