    if (r.meta_description_max_chars) lines.push('- Meta Description ≤ ' + r.meta_description_max_chars + ' حرفًا.');
    if (r.min_faq) lines.push('- قسم FAQ يحتوي على ' + r.min_faq + ' أسئلة على الأقل بصيغة H3.');
