  let inFence = false;
  for (const line of lines) {
    if (/^\s*```/.test(line)) inFence = !inFence;
    const h2 = !inFence && line.match(/^\s{0,3}##\s+(?!#)(.*)$/);
    if (h2) {
      out.push(cur);
      cur = { key: '', heading: h2[1].trim(), lines: [line] };
    } else {
      cur.lines.push(line);
    }
  }
