  (state.section_plan || []).forEach(function (p) { orderOf[p.key] = p.order; });
  kept.sort(function (a, b) {
    const oa = orderOf[a.key] != null ? orderOf[a.key] : 999;
    const ob = orderOf[b.key] != null ? orderOf[b.key] : 999;
    return oa - ob;
