  while ((m = re.exec(String(md || ''))) !== null) links.push('[' + m[1] + '](' + m[2] + ')');
  const heading = (String(md || '').match(/^\s{0,3}#{1,3}\s+(.*)$/m) || [])[1];
  const L = ['### عناصر لا يجوز حذفها أو تغييرها في هذا القسم'];
