      '### هوية العميل',
      '- الاسم: ' + (b.name || '-'),
      '- سنة التأسيس: ' + (b.founded || '-'),
      '- الدولة: ' + (b.country || '-'),
      '- الأسواق المستهدفة: ' + ((b.markets || []).join('، ') || '-'),
