  }
  L.push('- (للسياق: إجمالي المقال الآن ' + t.total_words + ' كلمة والمطلوب ' + t.want_words +
         (t.want_kw ? ' | إجمالي تكرار الكلمة ' + t.total_kw + ' والمطلوب ' + t.want_kw : '') + ')');
