    }
    if (r.choices && r.choices[0]) {
      const m = r.choices[0].message;
      if (m && typeof m.content === 'string') return m.content;
      if (m && Array.isArray(m.content)) {
        return m.content.map(function (c) { return c.text || ''; }).join('\n');
