    for (const block of r.content) {
      if (!block) continue;
      if (block.type === 'web_search_tool_result' && Array.isArray(block.content)) {
        for (const hit of block.content) {
          if (hit && hit.url) out.push({ url: hit.url, title: hit.title || '', age: hit.page_age || '' });
        }
