    }
    return out;
  },
  apiError(r) {
    if (!r) return 'empty response';
    if (r.error) return (r.error.type || 'error') + ': ' + (r.error.message || JSON.stringify(r.error));
    if (r.message && !r.content && !r.choices) return String(r.message);
