    }
    return null;
  },
  grabArticle(text) {
    if (!text) return '';
    const s = String(text);
    const m = s.match(/<<<ARTICLE>>>([\s\S]*?)<<<END_ARTICLE>>>/);
    if (m) return m[1].trim();
    const open = s.indexOf('<<<ARTICLE>>>');
    if (open >= 0) return s.slice(open + 13).trim();
