    if (!p) return 0;
    let n = 0, i = 0;
    while (true) {
      const k = h.indexOf(p, i);
      if (k < 0) break;
      n++; i = k + p.length;
    }
    return n;
  },
  parseArticle(md) {
    const raw = String(md || '');
    const out = {
      frontmatter: {}, body: raw, headings: [], blocks: [],
      links: [], internal_links: [], external_links: [],
