  L.push('- السوق المستهدف: ' + (b.target_market || (cfg.brand && cfg.brand.primary_market) || '-'));
  L.push('- الكلمة المفتاحية الرئيسية: «' + (b.primary_keyword || '-') + '»' + (b.primary_keyword_count ? ' — عدد مرات التكرار المطلوب: ' + b.primary_keyword_count : ''));
