H.minute(s, {
  stage: 'revise', actor: '🛠️ ' + H.persona(cfg, 'reviser').name,
  headline: 'سلّمت النسخة ' + s.round + ' (' + H.words(s.article) + ' كلمة) بعد تنفيذ ' + s.revision_brief.length + ' بندًا',
  detail: note
});

return [{ json: { state: s } }];

