  heads.forEach(function (h, i) {
    const share = declared > 0 ? (Number(h.word_budget) || 0) / declared : 1 / Math.max(1, heads.length);
    plan.push({
      key: 's' + (i + 1), order: i + 1,
      heading: h.heading || ('قسم ' + (i + 1)),
      purpose: h.purpose || '',
